export const experimentOptions={"vectors": {"a": [["10", "10 N"], ["20", "20 N"]], "b": [["-1", "Left"], ["1", "Right"]], "labels": ["Force magnitude", "Direction (right positive)"], "unit": "N signed force"}, "weight": {"a": [["2", "2 kg"], ["6", "6 kg"]], "b": [["2", "g = 2 N/kg"], ["10", "g = 10 N/kg"]], "labels": ["Mass", "Supplied field strength"], "unit": "N weight"}, "resultant": {"a": [["10", "Drive 10 N"], ["20", "Drive 20 N"]], "b": [["10", "Resistance 10 N"], ["15", "Resistance 15 N"]], "labels": ["Rightward drive", "Leftward resistance"], "unit": "N resultant"}, "components": {"a": [["3", "Horizontal 3 N"], ["6", "Horizontal 6 N"]], "b": [["4", "Vertical 4 N"], ["8", "Vertical 8 N"]], "labels": ["Horizontal component", "Vertical component"], "unit": "N magnitude (round to 0.001 N)"}, "work": {"a": [["10", "10 N"], ["30", "30 N"]], "b": [["2", "2 m"], ["4", "4 m"]], "labels": ["Force", "Along-force distance"], "unit": "J work"}, "elasticity": {"a": [["100", "k = 100 N/m"], ["200", "k = 200 N/m"]], "b": [["2", "2 N"], ["4", "4 N"]], "labels": ["Spring constant", "Applied force"], "unit": "m extension"}, "springs": {"a": [["100", "Toy spring k100 N/m"], ["200", "Toy spring k200 N/m"]], "b": [["0.01", "0.01 m"], ["0.03", "0.03 m"]], "labels": ["Spring", "Extension"], "unit": "N applied force"}, "moments": {"a": [["4", "4 N"], ["8", "8 N"]], "b": [["0.5", "0.5 m"], ["1", "1 m"]], "labels": ["Applied force", "Perpendicular distance"], "unit": "N m moment"}, "pressure": {"a": [["100", "100 N"], ["200", "200 N"]], "b": [["0.2", "0.2 m²"], ["0.4", "0.4 m²"]], "labels": ["Normal force", "Area"], "unit": "Pa pressure"}, "depth": {"a": [["1", "1 m"], ["3", "3 m"]], "b": [["800", "800 kg/m³"], ["1000", "1000 kg/m³"]], "labels": ["Depth", "Density (g10 N/kg)"], "unit": "Pa column pressure"}, "atmosphere": {"a": [["low", "Lower altitude"], ["high", "Higher altitude"]], "b": [["A", "Dataset A:100/80 kPa"], ["B", "Dataset B:98/78 kPa"]], "labels": ["Altitude", "Supplied dataset"], "unit": "kPa pressure"}, "motion": {"a": [["2", "2 m/s"], ["4", "4 m/s"]], "b": [["3", "3 s"], ["6", "6 s"]], "labels": ["Constant speed", "Time"], "unit": "m distance"}, "distancegraph": {"a": [["12", "12 m rise"], ["24", "24 m rise"]], "b": [["3", "3 s run"], ["6", "6 s run"]], "labels": ["Distance change", "Time change"], "unit": "m/s gradient"}, "acceleration": {"a": [["1", "1 m/s²"], ["2", "2 m/s²"]], "b": [["2", "2 s"], ["4", "4 s"]], "labels": ["Constant acceleration from rest", "Time"], "unit": "m/s final velocity"}, "velocitygraph": {"a": [["6", "Velocity rise6 m/s"], ["12", "Velocity rise12 m/s"]], "b": [["2", "2 s"], ["4", "4 s"]], "labels": ["Velocity change", "Elapsed time"], "unit": "m/s² acceleration"}, "terminal": {"a": [["10", "Weight10 N"], ["20", "Weight20 N"]], "b": [["10", "Drag10 N"], ["15", "Drag15 N"]], "labels": ["Weight", "Upward drag"], "unit": "N downward resultant"}, "firstlaw": {"a": [["ideal", "No resistance"], ["resist", "Resistance present"]], "b": [["balance", "Drive balances resistance"], ["remove", "Drive removed"]], "labels": ["Track condition", "Drive condition"], "unit": "velocity change", "choices": [["0", "Constant velocity"], ["1", "Velocity changes"]]}, "secondlaw": {"a": [["4", "4 N resultant"], ["8", "8 N resultant"]], "b": [["2", "2 kg"], ["4", "4 kg"]], "labels": ["Resultant force", "Moving mass"], "unit": "m/s² acceleration"}, "accelpractical": {"a": [["6", "6 N resultant"], ["12", "12 N resultant"]], "b": [["3", "3 kg total"], ["6", "6 kg total"]], "labels": ["Supplied resultant", "Total moving mass"], "unit": "m/s² acceleration"}, "thirdlaw": {"a": [["10", "10 N magnitude"], ["20", "20 N magnitude"]], "b": [["-1", "A-on-B points left"], ["1", "A-on-B points right"]], "labels": ["Force magnitude", "A-on-B direction"], "unit": "N B-on-A (right positive)"}, "stopping": {"a": [["10", "10 m/s"], ["20", "20 m/s"]], "b": [["0.4", "0.4 s"], ["0.8", "0.8 s"]], "labels": ["Speed", "Reaction time"], "unit": "m thinking distance"}, "braking": {"a": [["10", "10 m/s"], ["20", "20 m/s"]], "b": [["2500", "2500 N"], ["5000", "5000 N"]], "labels": ["Initial speed (mass1000 kg)", "Constant braking force"], "unit": "m ideal braking distance"}, "momentum": {"a": [["2", "2 kg"], ["4", "4 kg"]], "b": [["-3", "−3 m/s"], ["3", "+3 m/s"]], "labels": ["Mass", "Velocity (right positive)"], "unit": "kg m/s momentum"}, "collisions": {"a": [["2", "2 kg incoming"], ["4", "4 kg incoming"]], "b": [["2", "2 m/s incoming"], ["4", "4 m/s incoming"]], "labels": ["Incoming mass (target2 kg)", "Incoming velocity"], "unit": "m/s final common velocity"}, "impact": {"a": [["4", "Initial4 m/s"], ["8", "Initial8 m/s"]], "b": [["0.2", "0.2 s"], ["0.4", "0.4 s"]], "labels": ["Initial speed (mass2 kg, final rest)", "Stopping time"], "unit": "N average force magnitude"}};
export const tasksForFrc1=(k,tier="Higher")=>frc1Tasks[k].filter(t=>!t.higher||tier==="Higher");
export const validFrc1=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericFrc1=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advanceFrc1=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;

export function experimentResult(k,a,b){const o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated settings.');const x=Number(a),y=Number(b);let value;
if(['vectors','weight','work','springs','moments','motion','acceleration','stopping','momentum'].includes(k))value=x*y;
if(['resultant','terminal'].includes(k))value=x-y;
if(k==='thirdlaw')value=-x*y;
if(k==='components')value=Math.sqrt(x*x+y*y);
if(['elasticity'].includes(k))value=y/x;
if(['pressure','distancegraph','velocitygraph','secondlaw','accelpractical'].includes(k))value=x/y;
if(k==='depth')value=x*y*10;
if(k==='atmosphere')value=(a==='low'?100:80)-(b==='B'?2:0);
if(k==='firstlaw')value=a==='resist'&&b==='remove'?1:0;
if(k==='braking')value=.5*1000*x*x/y;
if(k==='collisions')value=x*y/(x+2);
if(k==='impact')value=2*x/y;
return{value,a,b};}
export const predictionValid=(k,v,r)=>experimentOptions[k].choices?String(v)===String(r.value):numericFrc1(v,r.value);
export const outputLabel=(k,v)=>experimentOptions[k].choices?.find(x=>String(x[0])===String(v))?.[1]??Number(Number(v).toFixed(3))+' '+experimentOptions[k].unit;
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
